import{_ as a,o as e,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"正则表达式匹配信用卡","description":"最近在做支付相关的服务，需要检测用户输入的信用卡号是否合法，并且根据信用卡号规则显示对应的信用卡类型。这里记录一下如何使用正则表达式来匹配信用卡号。顺便说一下只有 AE 卡号的 CVV 是 4 位的，其他的都是 3 位。","frontmatter":{"title":"正则表达式匹配信用卡","date":"2023-07-09 13:41","comments":true,"archives":2023,"tags":["regex"]},"headers":[],"relativePath":"posts/2023-07-09-credit-regex/index.md","filePath":"posts/2023/2023-07-09-credit-regex.md"}'),p={name:"posts/2023-07-09-credit-regex/index.md"};function o(r,s,t,c,i,d){return e(),n("div",null,[...s[0]||(s[0]=[l('<p>最近在做支付相关的服务，需要检测用户输入的信用卡号是否合法，并且根据信用卡号规则显示对应的信用卡类型。这里记录一下如何使用正则表达式来匹配信用卡号。顺便说一下只有 AE 卡号的 CVV 是 4 位的，其他的都是 3 位。</p><h2 id="银联卡" tabindex="-1">银联卡 <a class="header-anchor" href="#银联卡" aria-label="Permalink to &quot;银联卡&quot;">​</a></h2><p>银联卡以 62 开头，借记卡是 19 位，信用卡是 14 位。一般支付的时候都是使用信用卡，所以我们只需要匹配 14 位的卡号。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^62</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{14}&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="visa" tabindex="-1">Visa <a class="header-anchor" href="#visa" aria-label="Permalink to &quot;Visa&quot;">​</a></h2><p>Visa 信用卡以 4 开头，新卡长度为 16 位，旧卡长度为 13 位。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^4[0-9]{12}(?:[0-9]{3})?&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="mastercard" tabindex="-1">MasterCard <a class="header-anchor" href="#mastercard" aria-label="Permalink to &quot;MasterCard&quot;">​</a></h2><p>MasterCard 信用卡以 51 到 55 开头或者是以 2221–2720 开头，长度为 16 位。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^(5[1-5]</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{0,2}|22[2-9]</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{1}|2[3-7]</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{2})</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{12}&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="amex" tabindex="-1">Amex <a class="header-anchor" href="#amex" aria-label="Permalink to &quot;Amex&quot;">​</a></h2><p>Amex 信用卡以 34 或者 37 开头，长度为 15 位。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^3[47]</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{13}&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="jcb" tabindex="-1">Jcb <a class="header-anchor" href="#jcb" aria-label="Permalink to &quot;Jcb&quot;">​</a></h2><p>Jcb 信用卡以 35 开头，长度为 16 位。以 2131 或者 1800 开头，长度为 15 位。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^(?:2131|1800|35</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{3})</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{11}&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="diners" tabindex="-1">Diners <a class="header-anchor" href="#diners" aria-label="Permalink to &quot;Diners&quot;">​</a></h2><p>Diners 信用卡以 36、38 或者 30[0-5] 开头，长度为 14 位。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> regex</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> RegExp</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;^3(?:0([0-5]|9)|[68]</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d)</span><span style="color:#005CC5;">\\\\</span><span style="color:#032F62;">d{11}&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>信用卡号的判断并不复杂，但是很多卡号有些特殊情况，需要注意。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://en.wikipedia.org/wiki/Payment_card_number" target="_blank" rel="noreferrer">Payment card number</a></p><p><a href="https://www.regular-expressions.info/creditcard.html" target="_blank" rel="noreferrer">Finding or Verifying Credit Card Numbers</a></p>',24)])])}const u=a(p,[["render",o]]);export{b as __pageData,u as default};
